-- ============================================================================
--  FÊNIX ESTÉTICA — DADOS PRINCIPAIS (parte 1 de 3)
--  Importação dos dados do projeto antigo → projeto novo (Supabase CLI)
--  PRÉ-REQUISITO: ter criado a conta da clínica no app do projeto NOVO
--  (o script dá tudo pra conta mais recente do auth = a que você criou).
--  Idempotente: pode rodar de novo — nada duplica (on conflict do nothing).
--  Como rodar:  supabase db execute -f EsteArquivo.sql
--        (ou colar tudo no SQL Editor do dashboard e Run)
-- ============================================================================


-- conta nova vira a clínica "clinica principal" (mesma key e nome de antes)
insert into public.clinics (id,key,nome,criado_em,updated_at)
select n.id,'clinicaprincipal','clinica principal',now(),now() from (select id from auth.users order by created_at desc limit 1) n
on conflict (id) do nothing;


